<?php
declare(strict_types=1);
require __DIR__.'/ticket_test_support.php';
$f=fixtures();act($f['hr']);$today=date('Y-m-d');
function employee(int $id):array{return EmployeeApproverAssignmentService::employee($id);}
function route(int $id,?string $date=null):array{return EmployeeApproverAssignmentService::resolve(employee($id),$date??date('Y-m-d'));}
function form(array $ids,int $uid,string $kind='MANAGER',?string $from=null,?string $to=null):array{return ['employee_ids'=>$ids,'approver_user_id'=>$uid,'approver_type'=>$kind,'effective_from'=>$from??date('Y-m-d'),'effective_to'=>$to];}
check('HO needs Manager',route($f['requester'])['type']==='MANAGER');
check('branch needs ADL',route($f['branch_requester'])['type']==='ADL');
check('missing approver has ask-HR message',str_contains(route($f['requester'])['reason'],'Please ask HR'));
db()->prepare('UPDATE employees SET manager_employee_id=? WHERE id=?')->execute([$f['manager_employee'],$f['requester']]);
check('proven HO Reporting To resolves',route($f['requester'])['user_id']===$f['manager']['id']);
check('HO source provenance',route($f['requester'])['provenance']==='LEGACY_EMPLOYEE');
db()->prepare('UPDATE payroll_site_settings SET approver_user_id=? WHERE branch_id=?')->execute([$f['adl']['id'],$f['branch']]);
check('valid site ADL fallback resolves',route($f['branch_requester'])['user_id']===$f['adl']['id']);
check('site fallback provenance',route($f['branch_requester'])['provenance']==='LEGACY_SITE');
db()->prepare('UPDATE payroll_site_settings SET approver_user_id=? WHERE branch_id=?')->execute([$f['manager']['id'],$f['branch']]);
check('wrong site permission rejected',route($f['branch_requester'])['user_id']===null);
db()->prepare('UPDATE payroll_site_settings SET approver_user_id=? WHERE branch_id=?')->execute([$f['adl']['id'],$f['branch']]);
db()->prepare('UPDATE users SET status="INACTIVE" WHERE id=?')->execute([$f['adl']['id']]);
check('inactive site account rejected',route($f['branch_requester'])['user_id']===null);
db()->prepare('UPDATE users SET status="ACTIVE" WHERE id=?')->execute([$f['adl']['id']]);
db()->prepare('UPDATE payroll_site_settings SET approver_user_id=? WHERE branch_id=?')->execute([$f['manager']['id'],$f['ho']]);
db()->prepare('UPDATE employees SET manager_employee_id=NULL WHERE id=?')->execute([$f['requester']]);
check('HO never borrows branch fallback',route($f['requester'])['user_id']===null);
check('self approval forbidden',rejects(fn()=>EmployeeApproverAssignmentService::preview(form([$f['manager_employee']],$f['manager']['id']))));
check('wrong account permission forbidden',rejects(fn()=>EmployeeApproverAssignmentService::preview(form([$f['requester']],$f['adl']['id']))));
check('mixed HO/branch bulk blocked',rejects(fn()=>EmployeeApproverAssignmentService::preview(form([$f['requester'],$f['branch_requester']],$f['manager']['id']))));
check('invalid employee ID rejected',rejects(fn()=>EmployeeApproverAssignmentService::preview(form([999999999],$f['manager']['id']))));
check('invalid effective date rejected',rejects(fn()=>EmployeeApproverAssignmentService::preview(form([$f['requester']],$f['manager']['id'],'MANAGER','2026-02-30'))));
check('backdated assignment rejected',rejects(fn()=>EmployeeApproverAssignmentService::preview(form([$f['requester']],$f['manager']['id'],'MANAGER','2000-01-01'))));
$count=(int)db()->query('SELECT COUNT(*) FROM employee_approver_assignments')->fetchColumn();
$preview=EmployeeApproverAssignmentService::preview(form([$f['requester']],$f['manager']['id']));
check('preview does not mutate assignments',(int)db()->query('SELECT COUNT(*) FROM employee_approver_assignments')->fetchColumn()===$count);
check('bulk save returns count',EmployeeApproverAssignmentService::save($preview)===1);
check('new effective assignment resolves',route($f['requester'])['user_id']===$f['manager']['id']);
$assignment=row('SELECT * FROM employee_approver_assignments WHERE employee_id=? ORDER BY id DESC LIMIT 1',[$f['requester']]);
check('HR actor and provenance recorded',(int)$assignment['assigned_by']===$f['hr']['id'] && $assignment['provenance']==='HR_BULK');
check('legacy Reporting To untouched',employee($f['requester'])['manager_employee_id']===null);
check('stale preview cannot replay',rejects(fn()=>EmployeeApproverAssignmentService::save($preview)));
$next=EmployeeApproverAssignmentService::preview(form([$f['requester']],$f['manager']['id']));EmployeeApproverAssignmentService::save($next);
check('same-day history preserved as superseded',row('SELECT superseded_at FROM employee_approver_assignments WHERE id=?',[$assignment['id']])['superseded_at']!==null);
check('assignment changes audited',(int)row('SELECT COUNT(*) n FROM audit_logs WHERE module="HR Requests" AND record_type="employee" AND record_id=?',[$f['requester']])['n']>=3);
$future=(new DateTimeImmutable('today'))->modify('+10 days')->format('Y-m-d');
EmployeeApproverAssignmentService::save(EmployeeApproverAssignmentService::preview(form([$f['requester']],$f['manager']['id'],'MANAGER',$future)));
check('future assignment does not overlap previous',row('SELECT effective_to FROM employee_approver_assignments WHERE employee_id=? AND superseded_at IS NULL AND effective_from=?',[$f['requester'],$today])['effective_to']===(new DateTimeImmutable($future))->modify('-1 day')->format('Y-m-d'));
check('future overlap rejected',rejects(fn()=>EmployeeApproverAssignmentService::preview(form([$f['requester']],$f['manager']['id']))));
$p=EmployeeApproverAssignmentService::preview(form([$f['branch_requester']],$f['adl']['id'],'ADL'));
db()->prepare('UPDATE employees SET branch_id=? WHERE id=?')->execute([$f['ho'],$f['branch_requester']]);
check('concurrent employee changes reject save',rejects(fn()=>EmployeeApproverAssignmentService::save($p)));
db()->prepare('UPDATE employees SET branch_id=? WHERE id=?')->execute([$f['branch'],$f['branch_requester']]);
act($f['employee']);
check('employee denied HR report',rejects(fn()=>EmployeeApproverAssignmentService::report([])));
check('employee denied candidate list',rejects(fn()=>EmployeeApproverAssignmentService::candidates('MANAGER')));
check('employee denied preview',rejects(fn()=>EmployeeApproverAssignmentService::preview(form([$f['requester']],$f['manager']['id']))));
check('employee denied save/IDOR',rejects(fn()=>EmployeeApproverAssignmentService::save($p)));
db()->prepare('INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT ?,id FROM permissions WHERE code="tickets.approvers.manage"')->execute([$f['employee']['role_id']]);Auth::clearPermissionCache();
check('employee portal denied even with assignment permission',rejects(fn()=>EmployeeApproverAssignmentService::report([])));
act($f['hr']);
$report=EmployeeApproverAssignmentService::report(['business_unit_id'=>$f['company']]);
check('company-name filter isolates employees',$report['total']===4);
check('report pagination bounded',count($report['rows'])<=50);
$bulkIds=[];
foreach([1,2] as $n)$bulkIds[]=insert('INSERT INTO employees(employee_no,first_name,last_name,branch_id,legal_entity_id,business_unit_id,status) VALUES(?,"Slice15",?, ?,?,?,"ACTIVE")',[$f['tag'].'_bulk'.$n,'Bulk Test '.$n,$f['ho'],$f['legal'],$f['company']]);
$bulk=EmployeeApproverAssignmentService::preview(form($bulkIds,$f['manager']['id']));
check('bulk save handles multiple employees',EmployeeApproverAssignmentService::save($bulk)===2);
check('both bulk targets resolve',route($bulkIds[0])['user_id']===$f['manager']['id'] && route($bulkIds[1])['user_id']===$f['manager']['id']);
$bulk=EmployeeApproverAssignmentService::preview(form($bulkIds,$f['manager']['id']));
db()->prepare('UPDATE employees SET status="INACTIVE" WHERE id=?')->execute([$bulkIds[1]]);
$before=(int)db()->query('SELECT COUNT(*) FROM employee_approver_assignments')->fetchColumn();
check('bulk rejects stale member atomically',rejects(fn()=>EmployeeApproverAssignmentService::save($bulk)) && (int)db()->query('SELECT COUNT(*) FROM employee_approver_assignments')->fetchColumn()===$before);
db()->prepare('UPDATE employees SET status="ACTIVE" WHERE id=?')->execute([$bulkIds[1]]);
$bf=EmployeeApproverAssignmentService::backfill();
$legacy=row('SELECT * FROM employee_approver_assignments WHERE employee_id=? AND provenance="LEGACY_SITE"',[$f['branch_requester']]);
check('proven site backfilled with unknown HR actor',(int)$legacy['approver_user_id']===$f['adl']['id'] && $legacy['assigned_by']===null && $legacy['source_reference']==='payroll_site_settings:'.$f['branch']);
check('backfill observation starts today',$legacy['effective_from']===$today);
$bf2=EmployeeApproverAssignmentService::backfill();check('backfill rerun is idempotent',$bf2['inserted']===0);
finish();
